import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"科技空岛","description":"从一座空岛到自己的自动化工厂：了解 PotgCraft 的漂流钓鱼、岛屿成长、资源生产与科技模组玩法。","frontmatter":{"title":"科技空岛","description":"从一座空岛到自己的自动化工厂：了解 PotgCraft 的漂流钓鱼、岛屿成长、资源生产与科技模组玩法。"},"headers":[],"relativePath":"skyblock/index.md","filePath":"skyblock/index.md"}`),a={name:`skyblock/index.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="科技空岛-从一座空岛-到自己的工厂" tabindex="-1">科技空岛：从一座空岛，到自己的工厂 <a class="header-anchor" href="#科技空岛-从一座空岛-到自己的工厂" aria-label="Permalink to “科技空岛：从一座空岛，到自己的工厂”">​</a></h1><p>脚下是一小片土地，远处是虚空。先种下一棵树，想办法获得第一批材料，再为基地添上一台机器——科技空岛的乐趣，就藏在这些一点点发生的变化里。</p><p>这里是 <strong>Minecraft Java 1.21.1 模组环境</strong>。从空岛生存与资源成长起步，你可以亲手搭建生产线，规划能源、物流与自动合成，也可以和朋友分工，把悬空的基地建成既能运转、也能好好生活的地方。</p><div class="quick-links" aria-label="科技空岛快捷入口"><a href="./getting-started.html">第一次上岛</a><a href="./fishing-rewards.html">查漂流奖池</a><a href="./commands.html">查常用命令</a><a href="#join">客户端与加入方式</a></div><h2 id="把鱼竿抛向虚空" tabindex="-1">把鱼竿抛向虚空 <a class="header-anchor" href="#把鱼竿抛向虚空" aria-label="Permalink to “把鱼竿抛向虚空”">​</a></h2><p>空岛的资源并不只来自脚下。使用专用漂流鱼竿，在空旷处向空气抛竿，等待咬钩，就有机会带回沙砾、黏土球、树苗和作物种源。</p><p>从拾荒竿到星海竿，六个等级各有自己的奖池。有的帮你补齐开局材料，有的带来新的生态资源和收藏品。高等级并不包含所有低等级掉落，想收集某种材料时，选对鱼竿也很有用。</p><p><a href="./fishing.html">先看漂流钓鱼怎么玩</a> · <a href="./fishing-rewards.html">直接查六级完整奖池</a></p><h2 id="给岛屿找一个小目标" tabindex="-1">给岛屿找一个小目标 <a class="header-anchor" href="#给岛屿找一个小目标" aria-label="Permalink to “给岛屿找一个小目标”">​</a></h2><p>不知道接下来做什么，可以打开任务菜单，看看矿工、农夫、渔夫等方向的成长目标。任务奖励包含物资、游戏内货币，以及推进生成器或漂流鱼竿成长的相关奖励，具体条件以当前菜单为准。</p><p>鱼竿升级会用到对应芯片、前一级鱼竿与材料。别急着丢掉旧竿，先看清升级要求和目标奖池。初始鱼竿的发放方式与第六级完整升阶流程仍待确认。</p><p><a href="./resources.html">了解任务与资源成长</a></p><h2 id="空岛没有矿洞-资源生产要慢慢规划" tabindex="-1">空岛没有矿洞，资源生产要慢慢规划 <a class="header-anchor" href="#空岛没有矿洞-资源生产要慢慢规划" aria-label="Permalink to “空岛没有矿洞，资源生产要慢慢规划”">​</a></h2><p>空岛没有随处可挖的大型矿洞，但你可以逐步提升生成器的产矿能力。随着岛屿成长，基础矿物和科技工业所需的原料，也会成为生产计划的一部分。</p><p>产矿存在<strong>岛屿共享额度与按时间恢复的机制</strong>。多摆设备不会让共享额度消失；安排材料用途、提升加工效率，往往比只追求刷矿速度更有意义。</p><p><a href="./resources.html#quota">查看生成器与额度说明</a></p><h2 id="让零散机器连成生产线" tabindex="-1">让零散机器连成生产线 <a class="header-anchor" href="#让零散机器连成生产线" aria-label="Permalink to “让零散机器连成生产线”">​</a></h2><p>你可以按自己的兴趣组合这些系统，不需要先“通关”某个模组，才能开始研究另一个。</p><h3 id="让材料动起来" tabindex="-1">让材料动起来 <a class="header-anchor" href="#让材料动起来" aria-label="Permalink to “让材料动起来”">​</a></h3><p><strong>Create（机械动力）</strong>用齿轮、传动轴和传送带，把加工过程变成看得见的机械结构。<strong>Create Crafts &amp; Additions</strong>提供机械动力与电力系统之间的衔接，让不同设备有更多组合方式。</p><h3 id="为工厂供能-认真处理每一份原料" tabindex="-1">为工厂供能，认真处理每一份原料 <a class="header-anchor" href="#为工厂供能-认真处理每一份原料" aria-label="Permalink to “为工厂供能，认真处理每一份原料”">​</a></h3><p><strong>Mekanism（通用机械）</strong>提供电力、化学处理与多阶段矿物加工；<strong>Mekanism: Generators</strong>补上发电体系。<strong>Ender IO</strong>的机器与导管可以用于加工和自动化连接，<strong>Industrial Foregoing</strong>则能帮助农业与资源生产逐步机器化。</p><h3 id="东西多了-也要找得到" tabindex="-1">东西多了，也要找得到 <a class="header-anchor" href="#东西多了-也要找得到" aria-label="Permalink to “东西多了，也要找得到”">​</a></h3><p>开始时，可以用 <strong>Storage Drawers（储物抽屉）</strong>分类存放大批材料，用 <strong>Tom&#39;s Simple Storage</strong>把基础库存连起来。<strong>Pipez</strong>负责物品、流体和能源等资源的运输。</p><p>当你想统一管理库存、按需调用材料，再试试 <strong>Applied Energistics 2（AE2，应用能源）</strong>：ME 网络可以把存储和自动合成组织在一起。<strong>Applied Mekanistics</strong>扩展它与 Mekanism 的整合能力，减少在系统之间手工搬运和调度的操作。</p><h2 id="工厂旁边-也可以有厨房和花园" tabindex="-1">工厂旁边，也可以有厨房和花园 <a class="header-anchor" href="#工厂旁边-也可以有厨房和花园" aria-label="Permalink to “工厂旁边，也可以有厨房和花园”">​</a></h2><p>农夫乐事（Farmer&#39;s Delight）的作物与料理，让种植有了更多去处。用 <strong>FramedBlocks</strong>补齐工坊的建筑细节，用 <strong>Construction Sticks</strong>辅助批量放置，扩建岛屿时也能多花一点心思在外观上。</p><p>和朋友一起玩，可以有人负责能源，有人整理仓库，有人把机器房改成真正想住的家。成员与权限通过岛屿面板管理；邀请前先一起商量建设和资源使用的习惯。</p><h2 id="join" tabindex="-1">如何开始游玩 <a class="header-anchor" href="#join" aria-label="Permalink to “如何开始游玩”">​</a></h2><p><strong>需要匹配科技空岛的 Java 1.21.1 模组客户端，普通原版客户端不能直接游玩。</strong></p><p>目前，科技整合包正式下载地址、安装步骤，以及具体连接地址／子服选择方式仍待服主补充。请通过 <a href="https://qm.qq.com/q/qcQuFz2AwM" target="_blank" rel="noreferrer">现有 QQ 群</a> 询问最新安排，确认后再安装与连接。本站增强生存的旧客户端下载入口不适用于这里。</p><p>已经进入科技空岛？从 <a href="./getting-started.html">新手入门</a> 开始，先认识岛屿管理面板，再决定第一条产线怎么搭。</p><h2 id="开始前的几个小问题" tabindex="-1">开始前的几个小问题 <a class="header-anchor" href="#开始前的几个小问题" aria-label="Permalink to “开始前的几个小问题”">​</a></h2><h3 id="和增强生存的天堂空岛是同一个地方吗" tabindex="-1">和增强生存的天堂空岛是同一个地方吗？ <a class="header-anchor" href="#和增强生存的天堂空岛是同一个地方吗" aria-label="Permalink to “和增强生存的天堂空岛是同一个地方吗？”">​</a></h3><p>不是。天堂维度属于 <a href="./../server-intro.html">增强生存</a>；这里是独立的科技空岛子服。PotgCraft 目前只有这两个子服。</p><h3 id="两边的物品、余额和存档共用吗" tabindex="-1">两边的物品、余额和存档共用吗？ <a class="header-anchor" href="#两边的物品、余额和存档共用吗" aria-label="Permalink to “两边的物品、余额和存档共用吗？”">​</a></h3><p>目前没有已确认的背包、经济或存档互通，请分别规划两个子服的发展。</p><h3 id="奖池里有末地材料-能去独立末地岛吗" tabindex="-1">奖池里有末地材料，能去独立末地岛吗？ <a class="header-anchor" href="#奖池里有末地材料-能去独立末地岛吗" aria-label="Permalink to “奖池里有末地材料，能去独立末地岛吗？”">​</a></h3><p>科技空岛的独立末地岛当前未开放。末地石、紫颂花等可以出现在漂流奖池中，不代表完整末地玩法已经开放。</p><h3 id="新人也有十次死亡保护吗" tabindex="-1">新人也有十次死亡保护吗？ <a class="header-anchor" href="#新人也有十次死亡保护吗" aria-label="Permalink to “新人也有十次死亡保护吗？”">​</a></h3><p>增强生存的限次保护不能套用到这里。科技空岛的死亡掉落与新手保护规则仍待单独确认，起步时请留意角色安全。</p>`,41)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};